class LRUCache {
private:
    struct Node {
        int key;
        int value;
        Node* prev;
        Node* next;
        Node(int k, int v) : key(k), value(v), prev(nullptr), next(nullptr) {}
    };

    int cap;
    unordered_map<int, Node*> cache;
    Node* head; // dummy, MRU side
    Node* tail; // dummy, LRU side

    void detach(Node* node) {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }

    void insertAtFront(Node* node) {
        node->next = head->next;
        node->prev = head;
        head->next->prev = node;
        head->next = node;
    }

public:
    LRUCache(int capacity) {
        cap = capacity;
        head = new Node(0, 0);
        tail = new Node(0, 0);
        head->next = tail;
        tail->prev = head;
    }

    int get(int key) {
        auto it = cache.find(key);
        if (it == cache.end()) return -1;
        Node* node = it->second;
        detach(node);
        insertAtFront(node);
        return node->value;
    }

    void put(int key, int value) {
        auto it = cache.find(key);
        if (it != cache.end()) {
            Node* node = it->second;
            node->value = value;
            detach(node);
            insertAtFront(node);
            return;
        }
        Node* node = new Node(key, value);
        cache[key] = node;
        insertAtFront(node);
        if ((int)cache.size() > cap) {
            Node* lru = tail->prev;
            detach(lru);
            cache.erase(lru->key);
            delete lru;
        }
    }
};
